#include <bits/stdc++.h>
#define MAX_SIZE 30
#define MOD_CONST 1000000007
using namespace std;

long long totalCount;
int mVal, fArr[65][35][35], sArr[65], countNum, gArr[35][35], AArr[35], BArr[35];

inline int modSubtract(int x, int y) {
    return (x < mVal) ? (x - y + mVal) % mVal : (x - y + mVal) % mVal;
}

int main() {
    cin >> totalCount >> mVal;
    for (long long t = totalCount; t; t /= mVal) sArr[++countNum] = t % mVal;
    for (int i = 1; i <= mVal; ++i) fArr[1][i][i] = 1;
    for (int i = 0; i <= mVal; ++i) fArr[1][0][i] = 1;
    for (int i = 2; i <= countNum; ++i) {
        for (int j = 0; j <= mVal; ++j) fArr[i][j][j] = 1;
        for (int j = 0; j < mVal; ++j) {
            for (int a = 0; a <= mVal; ++a)
                for (int b = 0; b <= mVal; ++b)
                    for (int c = 0; c <= mVal; ++c)
                        gArr[a][c] = (gArr[a][c] + (long long)fArr[i - 1][modSubtract(a, j)][modSubtract(b, j)] * fArr[i][b][c]) % MOD_CONST;
            for (int a = 0; a <= mVal; ++a)
                for (int b = 0; b <= mVal; ++b)
                    fArr[i][a][b] = gArr[a][b], gArr[a][b] = 0;
        }
    }
    for (int i = 0; i <= mVal; ++i) AArr[i] = 1;
    for (int i = 1; i <= countNum; ++i) {
        int sumS = 0;
        for (int j = i + 1; j <= countNum; ++j) sumS = (sumS + sArr[j]) % mVal;
        for (; sArr[i]; --sArr[i]) {
            int decVal = (sumS + sArr[i]) % mVal;
            for (int a = 0; a <= mVal; ++a)
                for (int b = 0; b <= mVal; ++b)
                    BArr[b] = (BArr[b] + (long long)AArr[a] * fArr[i][modSubtract(a, decVal)][modSubtract(b, decVal)]) % MOD_CONST;
            for (int a = 0; a <= mVal; ++a) AArr[a] = BArr[a], BArr[a] = 0;
        }
    }
    cout << AArr[mVal] << "\n";
    return 0;
}
